import { pipe } from 'fp-ts-esm/function';
import type { ComponentType } from 'react';
import React, { useEffect, useState } from 'react';

import type { Selection } from './../tiptap/pm/state.js';
import type { Editor } from './../tiptap/react/index.js';

import { createRicosFunctionalExtension } from './create-ricos-extension/index.js';

const isInSelection = (selection: Selection) => (position: number) =>
  position >= selection.$from.pos && position <= selection.$to.pos;

const useIsSelected = (editor: Editor, getPos: () => number) => {
  const [isSelected, setSelected] = useState(false);

  useEffect(() => {
    const onSelectionUpdate = ({ editor }: $TSFixMe) =>
      pipe(getPos(), isInSelection(editor.state.selection), setSelected);
    editor.on('selectionUpdate', onSelectionUpdate);
    return () => {
      editor.off('selectionUpdate', onSelectionUpdate);
    };
  }, []);

  return isSelected;
};

const FocusHoc = (Component: ComponentType) => {
  const Focus = (props: $TSFixMe) => (
    <Component {...props} isFocused={useIsSelected(props.editor, props.getPos)} />
  );
  Focus.displayName = 'FocusHoc';
  return Focus;
};

export const focus = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'focus',
  createExtensionConfig() {
    return {
      name: this.name,
      priority: 20,
      addNodeHoc: () => ({
        priority: 100,
        nodeTypes: ['*'],
        getNodeHoc: () => FocusHoc,
      }),
    };
  },
});
