import type { ExtensionProps, NodeConfig, RicosExtension } from './../ricos-types/index.js';
import type { TiptapAdapterServices } from './../tiptap-editor/initialize-tiptap-adapter.js';

import { createRicosNodeExtension } from './create-ricos-extension/index.js';

export const keymapOverride = createRicosNodeExtension<{
  services: TiptapAdapterServices;
}>({
  name: 'keymap-override',
  groups: ['shortcuts-enabled'],
  type: 'html-node',
  reconfigure: (
    config: NodeConfig,
    _extensions: RicosExtension[],
    _props: ExtensionProps,
    settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) => {
    return {
      ...config,
      addOptions() {
        return {
          services,
          HTMLAttributes: {},
          ...settings,
        };
      },
    };
  },

  createExtensionConfig() {
    return {
      name: this.name,
      inline: true,
      group: 'inline',
      priority: Infinity,

      selectable: false,

      addKeyboardShortcuts() {
        const tiptapKeyboardShortcuts: any = {};

        //TODO: move to shortcut agregate
        const needToCancelEnter = this.options.services.shortcuts
          .asArray()
          .some(s => s.getName() === 'Enter');

        if (needToCancelEnter) {
          tiptapKeyboardShortcuts.Enter = () => true;
        }

        // Disable Tiptap's default Ctrl+A behavior, as we have our own incremental selection
        tiptapKeyboardShortcuts['Mod-a'] = () => true;

        return {
          ...tiptapKeyboardShortcuts,
        };
      },
    };
  },
});
