import type { PmConverters } from './../pm-converters/collect.js';
import type { Decoration, Decoration_Type, DocumentStyle, Node } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { TextBlockNodeType } from './../ricos-styles/index.js';
import { DocumentStyle as RicosDocumentStyle } from './../ricos-styles/index.js';
import type {
  AmbientStyles,
  ExtensionProps,
  HeadingNode,
  ParagraphNode,
  RicosExtension,
} from './../ricos-types/index.js';
import { Mark_Type } from './../ricos-types/index.js';
import type { PmHeadingNode, PmParagraphNode } from './../_shared/pm-node-types.js';
import { getMarksBetween } from './../tiptap/index.js';
import type { CommandProps, Editor, ExtensionConfig } from './../tiptap/core/index.js';
import type { Node as ProseMirrorNode } from './../tiptap/pm/model.js';
import type { EditorState } from './../tiptap/pm/state.js';
import { Step, StepResult } from './../tiptap/pm/transform.js';
import type { TiptapAdapterServices } from './../tiptap-editor/initialize-tiptap-adapter.js';

import { createRicosFunctionalExtension } from './create-ricos-extension/index.js';

const STEP_TYPE = 'setDocAttr';

const DOCUMENT_STYLES_MARKS = [
  Mark_Type.BOLD,
  Mark_Type.ITALIC,
  Mark_Type.COLOR_BACKGROUND,
  Mark_Type.COLOR_FOREGROUND,
  Mark_Type.FONT_SIZE,
] as string[];

// adapted from https://discuss.prosemirror.net/t/changing-doc-attrs/784
class SetDocAttrStep extends Step {
  private prevValue: $TSFixMe;

  constructor(
    private key: string,
    private value: $TSFixMe
  ) {
    super();
    this.key = key;
    this.value = value;
  }

  get stepType() {
    return STEP_TYPE;
  }

  apply(doc: $TSFixMe) {
    this.prevValue = doc.attrs[this.key];
    // avoid clobbering doc.type.defaultAttrs
    if (doc.attrs === doc.type.defaultAttrs) {
      doc.attrs = Object.assign({}, doc.attrs);
    }
    doc.attrs[this.key] = this.value;
    return StepResult.ok(doc);
  }

  invert() {
    return new SetDocAttrStep(this.key, this.prevValue);
  }

  // position never changes so map should always return same step
  map() {
    return this;
  }

  toJSON() {
    return {
      stepType: this.stepType,
      key: this.key,
      value: this.value,
    };
  }

  static fromJSON(schema: $TSFixMe, json: $TSFixMe) {
    return new SetDocAttrStep(json.key, json.value);
  }

  static register() {
    try {
      Step.jsonID(STEP_TYPE, SetDocAttrStep);
    } catch (err) {
      if ((err as Error).message !== `Duplicate use of step JSON ID ${STEP_TYPE}`) {
        throw err;
      }
    }
    return true;
  }
}

declare module './../tiptap/core' {
  interface Commands<ReturnType> {
    styles: {
      /**
       * returns decoration object from selected node according to ricos-styles
       */
      getStylesDecorationBySelectedNode: (
        decorationType: Decoration_Type
      ) => (props: CommandProps) => Decoration | undefined;
      /**
       * updates the document style
       */
      updateDocumentStyle: (documentStyle: DocumentStyle) => ReturnType;
      /**
       * updates the document style according to the selected node
       */
      updateDocumentStyleBySelectedNode: () => ReturnType;
      /**
       * remove all marks that are defined in the document style (bold, italic, color, font size)
       */
      unsetAllDocumentStyleMarksByNode: (node: ProseMirrorNode) => ReturnType;
      /**
       * remove all attibutes that are defined in the document style (paddingTop,paddingBottom,lineHeight)
       */
      unsetAllDocumentStyleAttrsByNode: (node: ProseMirrorNode, pos: number) => ReturnType;
      /**
       * reset the document style of a given nodeType
       */
      resetDocumentStyleByNodeType: (nodeType: TextBlockNodeType) => ReturnType;
    };
  }
}

export const getStylesDecorationBySelectedNode = (
  decorationType: Decoration_Type,
  {
    state,
    styles,
    pmConverters,
  }: { state: EditorState; styles: AmbientStyles; pmConverters: PmConverters }
) => {
  const { from, to } = state.selection;
  let node: Node | undefined;
  state.doc.nodesBetween(from, to, currNode => {
    if ([Node_Type.PARAGRAPH, Node_Type.HEADING].includes(currNode?.type?.name as any)) {
      node = pmConverters.fromPmNode(currNode.toJSON()) as unknown as Node;
      return false;
    }
  });
  return node && styles.getDecoration(node as ParagraphNode | HeadingNode, decorationType);
};

export const getLineHeightStyleBySelectedNode = ({
  tiptapEditor,
  styles,
}: {
  tiptapEditor: Editor;
  styles: AmbientStyles;
}) => {
  const { state, view } = tiptapEditor;
  const { from, to, $from } = state.selection;

  const domNode = $from.depth > 0 ? view.nodeDOM($from.before($from.depth)) : null;

  let node: PmParagraphNode | PmHeadingNode | undefined;

  state.doc.nodesBetween(from, to, currNode => {
    if ([Node_Type.PARAGRAPH, Node_Type.HEADING].includes(currNode?.type?.name as any)) {
      node = currNode.toJSON() as PmParagraphNode | PmHeadingNode;
      return false;
    }
  });

  return node ? styles.getComputedLineHeight(node, domNode as HTMLElement) : undefined;
};

export const ricosStyles = createRicosFunctionalExtension<{
  styles: AmbientStyles;
  converters: PmConverters;
}>({
  type: 'extension',
  groups: [],
  name: 'ricos-styles-commands',
  reconfigure: (
    config: ExtensionConfig,
    _extensions: RicosExtension[],
    _ricosProps: ExtensionProps,
    _settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) => {
    return {
      ...config,
      addOptions() {
        return {
          styles: services.styles,
          converters: services.converters,
        };
      },
    };
  },
  createExtensionConfig() {
    return {
      name: this.name,
      addCommands() {
        return {
          getStylesDecorationBySelectedNode:
            (decorationType: Decoration_Type) =>
            ({ state }) => {
              const { from, to } = state.selection;
              let node: Node | undefined;
              state.doc.nodesBetween(from, to, currNode => {
                if (
                  [Node_Type.PARAGRAPH, Node_Type.HEADING].includes(currNode?.type?.name as any)
                ) {
                  node = this.options.converters.fromPmNode(currNode.toJSON()) as unknown as Node;
                  return false;
                }
              });
              return (
                node &&
                this.options.styles.getDecoration(
                  node as ParagraphNode | HeadingNode,
                  decorationType
                )
              );
            },
          updateDocumentStyleBySelectedNode:
            () =>
            ({ state, chain }) => {
              const { from, to } = state.selection;
              let node: Node | undefined, proseNode: ProseMirrorNode | undefined;

              state.doc.nodesBetween(from, to, currNode => {
                if (
                  [Node_Type.PARAGRAPH, Node_Type.HEADING].includes(currNode?.type?.name as any)
                ) {
                  node = this.options.converters.fromPmNode(currNode.toJSON()) as unknown as Node;
                  proseNode = currNode;

                  return false;
                }
              });
              if (!proseNode || !node || !RicosDocumentStyle.isNodeTransformable(node)) {
                return false;
              }

              const documentStyleEntity = RicosDocumentStyle.fromNode(node);

              return chain()
                .focus()
                .updateDocumentStyle(documentStyleEntity.toContent())
                .command(({ state, commands }) => {
                  state.doc.descendants((node, pos) => {
                    if (
                      node.isTextblock &&
                      node.type.name === (proseNode as ProseMirrorNode).type.name
                    ) {
                      commands.unsetAllDocumentStyleMarksByNode(node);
                      commands.unsetAllDocumentStyleAttrsByNode(node, pos);
                    }
                  });
                  return true;
                })

                .run();
            },
          unsetAllDocumentStyleMarksByNode:
            (node: ProseMirrorNode) =>
            ({ editor, tr, state }) => {
              const nodeElement = document.body.querySelector(`[data-ricos-id="${node.attrs.id}"]`);
              if (nodeElement) {
                const start = editor.view.posAtDOM(nodeElement, 0);
                const end = start + node.content.size;

                getMarksBetween(start, end, state.doc).forEach(markRang => {
                  if (DOCUMENT_STYLES_MARKS.includes(markRang.mark.type.name)) {
                    tr.removeMark(start, end, markRang.mark);
                  }
                });
              }
              return true;
            },
          unsetAllDocumentStyleAttrsByNode:
            (node: ProseMirrorNode, pos: number) =>
            ({ tr }) => {
              const { style: _removedStyle, textStyle, ...restAttrs } = node.attrs;
              const attrs =
                textStyle && typeof textStyle === 'object'
                  ? {
                      ...restAttrs,
                      textStyle: (({ lineHeight: _removedLineHeight, ...textStyleRest }) =>
                        textStyleRest)(textStyle),
                    }
                  : restAttrs;
              tr.setNodeMarkup(pos, undefined, attrs);
              return true;
            },
          resetDocumentStyleByNodeType:
            nodeType =>
            ({ state }) => {
              const updatedDocumentStyle = new RicosDocumentStyle(state.doc.attrs.documentStyle)
                .resetStyle(nodeType)
                .toContent();

              state.tr.step(new SetDocAttrStep('documentStyle', updatedDocumentStyle));
              this.options.styles.setDocumentStyle(updatedDocumentStyle);
              return true;
            },
          updateDocumentStyle:
            (documentStyle: DocumentStyle) =>
            ({ state }) => {
              const updatedDocumentStyle = new RicosDocumentStyle(state.doc.attrs.documentStyle)
                .mergeWith(documentStyle)
                .toContent();
              state.tr.step(new SetDocAttrStep('documentStyle', updatedDocumentStyle));
              this.options.styles.setDocumentStyle(updatedDocumentStyle);
              return true;
            },
        };
      },
    };
  },
});
