import { TIPTAP_CARD_CONTENT_TYPE, TIPTAP_CARD_TYPE } from './../ricos-content/index.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { RicosExtension, RicosExtensionConfig } from './../ricos-types/index.js';
import { Plugin, PluginKey } from './../tiptap/pm/state.js';

import { createRicosFunctionalExtension } from './create-ricos-extension/index.js';

/**
 * Extension based on:
 * - https://github.com/ueberdosis/tiptap/blob/v1/packages/tiptap-extensions/src/extensions/TrailingNode.js
 * - https://github.com/remirror/remirror/blob/e0f1bec4a1e8073ce8f5500d62193e52321155b9/packages/prosemirror-trailing-node/src/trailing-node-plugin.ts
 */

export const trailingNode = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'trailingNode',
  reconfigure(config: RicosExtensionConfig, extensions: RicosExtension[]) {
    return {
      ...config,
      addOptions: () => ({
        node: Node_Type.PARAGRAPH,
        trailingInCard: !!extensions.find(e => e.name === TIPTAP_CARD_TYPE),
        notAfter: extensions
          .filter(({ groups }) => groups.includes('no-trailing-node'))
          .map(({ name }) => name),
      }),
    };
  },
  createExtensionConfig() {
    return {
      name: this.name,

      addProseMirrorPlugins() {
        const plugin = new PluginKey(this.name);
        return [
          new Plugin({
            key: plugin,
            appendTransaction: (_, __, state) => {
              const { doc, tr, schema } = state;

              if (this.options.trailingInCard) {
                const type = schema.nodes[this.options.node];
                let hasChanges = false;

                // Collect insertion positions first, then apply in reverse
                // to avoid position shifts from earlier inserts.
                // For each CARD, look inside its CARD_CONTENT child and insert a
                // trailing paragraph at the end of CARD_CONTENT (not directly into
                // CARD, which the schema doesn't allow).
                const insertPositions: number[] = [];
                doc.forEach((node, pos) => {
                  if (node.type.name !== Node_Type.CARD) {
                    return;
                  }
                  node.forEach((wrapper, wrapperOffset) => {
                    if (wrapper.type.name !== TIPTAP_CARD_CONTENT_TYPE) {
                      return;
                    }
                    const lastChild = wrapper.lastChild;
                    if (this.options.notAfter.includes(lastChild?.type.name)) {
                      return;
                    }
                    const wrapperEndInner = pos + 1 + wrapperOffset + wrapper.nodeSize - 1;
                    insertPositions.push(wrapperEndInner);
                  });
                });

                for (let i = insertPositions.length - 1; i >= 0; i--) {
                  tr.insert(insertPositions[i], type.create());
                  hasChanges = true;
                }

                if (hasChanges) {
                  return tr.setMeta('trailingNodeInsertion', true);
                }
                return;
              }

              const lastNode = state.tr.doc.lastChild;
              if (this.options.notAfter.includes(lastNode?.type.name)) {
                return;
              }
              const endPosition = doc.content.size;
              const type = schema.nodes[this.options.node];
              return tr.insert(endPosition, type.create()).setMeta('trailingNodeInsertion', true);
            },
          }),
        ];
      },
    };
  },
});
