import type { ExtensionProps, RicosExtension, RicosExtensionConfig } from './../ricos-types/index.js';
import { OverlayHoc } from './../_shared/overlay-hoc/overlay-hoc.js';

import { createRicosFunctionalExtension } from './create-ricos-extension/index.js';

export const overlay = createRicosFunctionalExtension({
  type: 'extension',
  name: 'overlay',
  groups: [],
  reconfigure: (
    config: RicosExtensionConfig,
    extensions: RicosExtension[],
    _props: ExtensionProps,
    settings: Record<string, unknown>
  ) => ({
    ...config,
    addOptions: () => settings,
    addNodeHoc: () => ({
      nodeTypes: extensions
        .filter(extension => extension.groups.includes('overlay'))
        .map(({ name }) => name),
      priority: 10,
      getNodeHoc: () => OverlayHoc,
    }),
  }),
  createExtensionConfig() {
    return {
      name: this.name,
      priority: 10,
    };
  },
});
