import { createRicosFunctionalExtension } from './create-ricos-extension/index.js';
import * as setNodeAlignment from './node-commands/set-node-alignment.js';
import * as setNodeSize from './node-commands/set-node-size.js';
import * as toggleNodeTextWrap from './node-commands/toggle-node-text-wrap.js';

export const commonNodeCommands = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'ricos-common-node-commands',
  createExtensionConfig() {
    return {
      name: this.name,
      addCommands() {
        return {
          ...setNodeSize,
          ...setNodeAlignment,
          ...toggleNodeTextWrap,
        };
      },
    };
  },
});
