import { ACTION_COLOR_DEFAULT } from './../ricos-styles/theme-constants.js';

import { createRicosFunctionalExtension } from './create-ricos-extension/index.js';
import { dropCursor } from './dropcursor-plugin.js';
import styles from './statics/styles-scss.js';

export const dropcursor = createRicosFunctionalExtension<{
  /**
    The color of the cursor. Defaults to `black`. Use `false` to apply no color and rely only on class.
    */
  color?: string | false;
  /**
    The precise width of the cursor in pixels. Defaults to 1.
    */
  width?: number;
  /**
    A CSS class name to add to the cursor element.
    */
  class?: string;
}>({
  name: 'dropCursor',
  groups: [],
  type: 'extension',

  createExtensionConfig() {
    return {
      name: this.name,
      addOptions() {
        return {
          color: ACTION_COLOR_DEFAULT,
          width: 2,
          class: styles.dropcursor,
        };
      },

      addProseMirrorPlugins() {
        return [dropCursor(this.options)];
      },
    };
  },
});
