import classNames from 'classnames';

import type {
  ExtensionPlaceholder,
  ExtensionProps,
  RicosExtension,
  RicosExtensionConfig,
  RicosNodeExtension,
} from './../ricos-types/index.js';
import { getIsEditorEmpty } from './../_shared/get-is-editor-empty.js';
import { TOP_LEVEL_NODES } from './../_shared/top-level-nodes.js';
import type { Editor } from './../tiptap/core/index.js';
import { Plugin, PluginKey } from './../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../tiptap/pm/view.js';
import type { EditorView } from './../tiptap/pm/view.js';
import type { TiptapAdapterServices } from './../tiptap-editor/initialize-tiptap-adapter.js';

import { createRicosFunctionalExtension } from './create-ricos-extension/index.js';
import styles from './placeholder-scss.js';

const PLACEHOLDER_UPDATE_META = 'placeholder-update';
const PLACEHOLDER_POINTER_META = 'placeholder-pointer-update';

type PluginState = {
  placeholder: string;
  suppressWidgets: boolean;
};

const createPlaceholderWidget = (text: string, isMobile: boolean) => () => {
  const wrapper = document.createElement('span');
  wrapper.contentEditable = 'false';
  wrapper.setAttribute('data-placeholder', text);
  if (isMobile) {
    wrapper.setAttribute('data-placeholder-multiline', '');
  }
  // Zero-width space (U+200B) gives Chrome a stable text node for caret
  // anchoring on arrow navigation without adding visible content to the DOM.
  wrapper.textContent = '\u200B';
  return wrapper;
};

const updatePointerSuppression = (
  view: EditorView,
  pluginKey: PluginKey<PluginState>,
  suppressWidgets: boolean
) => {
  if (pluginKey.getState(view.state)?.suppressWidgets === suppressWidgets) {
    return;
  }

  view.dispatch(view.state.tr.setMeta(PLACEHOLDER_POINTER_META, suppressWidgets));
};

export const placeholder = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'placeholder',
  reconfigure: (
    config: RicosExtensionConfig,
    _extensions: RicosExtension[],
    ricosProps: ExtensionProps,
    _settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) => ({
    ...config,
    addOptions() {
      return {
        isMobile: services?.context?.isMobile ?? false,
        placeholder: ricosProps.placeholder || '',
        t: services.t,
        extensionsPlaceholders: _extensions
          .filter((ext): ext is RicosNodeExtension =>
            ['html-node', 'react-node', 'extension'].includes(ext.type)
          )
          .map((ext: RicosNodeExtension) => ext.placeholder)
          .filter(x => !!x),
      };
    },
  }),
  createExtensionConfig() {
    return {
      name: this.name,
      addProseMirrorPlugins() {
        const pluginKey = new PluginKey<PluginState>('editor-placeholders');
        const options = this.options;
        const editor = this.editor;
        const pointerState = { isPointerDown: false };
        // Sort once at plugin construction. The previous code re-sorted
        // `extensionsPlaceholders` inside `doc.descendants`, which mutated
        // the array on every node visit on every view update.
        const sortedPlaceholders: ExtensionPlaceholder[] = [
          ...(options.extensionsPlaceholders as ExtensionPlaceholder[]),
        ].sort(({ priority: a = 0 }, { priority: b = 0 }) => b - a);

        return [
          new Plugin<PluginState>({
            key: pluginKey,
            state: {
              init: () => ({
                placeholder: options.placeholder,
                suppressWidgets: false,
              }),
              apply(tr, value) {
                const placeholderOverride = tr.getMeta(PLACEHOLDER_UPDATE_META);
                const suppressWidgetsOverride = tr.getMeta(PLACEHOLDER_POINTER_META);
                if (placeholderOverride === undefined && suppressWidgetsOverride === undefined) {
                  return value;
                }

                return {
                  placeholder:
                    placeholderOverride !== undefined ? placeholderOverride : value.placeholder,
                  suppressWidgets:
                    suppressWidgetsOverride !== undefined
                      ? suppressWidgetsOverride
                      : value.suppressWidgets,
                };
              },
            },
            view(view) {
              const requestClearSuppression = () => {
                pointerState.isPointerDown = false;
                const currentWindow = view.dom.ownerDocument.defaultView;
                if (!pluginKey.getState(view.state)?.suppressWidgets || !currentWindow) {
                  return;
                }

                // Let the browser finish the native drag-selection update
                // before we re-insert placeholder widgets into empty blocks.
                currentWindow.requestAnimationFrame(() => {
                  if (view.isDestroyed) {
                    return;
                  }

                  updatePointerSuppression(view, pluginKey, false);
                });
              };

              const currentDocument = view.dom.ownerDocument;
              const currentWindow = currentDocument.defaultView;

              currentDocument.addEventListener('mouseup', requestClearSuppression);
              currentDocument.addEventListener('dragend', requestClearSuppression);
              currentWindow?.addEventListener('blur', requestClearSuppression);

              return {
                destroy() {
                  pointerState.isPointerDown = false;
                  currentDocument.removeEventListener('mouseup', requestClearSuppression);
                  currentDocument.removeEventListener('dragend', requestClearSuppression);
                  currentWindow?.removeEventListener('blur', requestClearSuppression);
                },
              };
            },
            props: {
              handleDOMEvents: {
                mousedown(_view, event) {
                  if (event.button !== 0) {
                    return false;
                  }

                  pointerState.isPointerDown = true;
                  return false;
                },
                mousemove(view, event) {
                  if (!pointerState.isPointerDown || event.buttons !== 1) {
                    return false;
                  }

                  updatePointerSuppression(view, pluginKey, true);
                  return false;
                },
              },
              // Computed live, NOT cached in plugin state. Some predicates
              // (notably quick-actions) read `editor.isFocused`, which is
              // not part of editor state and does not flip via a transaction
              // — caching the resulting `DecorationSet` in `apply` would
              // leave the placeholder stale across focus/blur. The work
              // here is small (one `descendants` walk on an empty doc),
              // so the live read is the correct trade-off.
              decorations(state) {
                if (!editor.isEditable) {
                  return null;
                }

                const pluginState = pluginKey.getState(state);
                const placeholderText = pluginState?.placeholder ?? '';
                const shouldRenderWidgets = !pluginState?.suppressWidgets;
                const { doc, selection } = state;
                const decorations: Decoration[] = [];
                let editorEmptyTargetPos: number | undefined;
                let editorEmptyTargetNodeSize: number | undefined;
                const nodePlaceholderPositions = new Set<number>();

                if (getIsEditorEmpty(doc)) {
                  const { firstChild } = doc;
                  editorEmptyTargetPos = 0;
                  let targetNode = firstChild!;
                  // Walk through wrapper nodes (CARD → CARD_CONTENT → …) to reach
                  // the actual textblock. Each wrapper adds 1 to the position for
                  // its opening token.
                  while (
                    (TOP_LEVEL_NODES as readonly string[]).includes(targetNode.type.name) &&
                    targetNode.firstChild
                  ) {
                    editorEmptyTargetPos += 1;
                    targetNode = targetNode.firstChild;
                  }
                  editorEmptyTargetNodeSize = targetNode.nodeSize;
                }

                if (sortedPlaceholders.length) {
                  doc.descendants((node, pos) => {
                    const isEmpty = !node.isLeaf && !node.childCount;
                    if (!isEmpty) {
                      return;
                    }

                    const { content, alwaysVisible, alignCenter } =
                      sortedPlaceholders.find(({ predicate }) =>
                        predicate({
                          doc,
                          pos,
                          node,
                          selection,
                          editor,
                          isMobile: options.isMobile,
                        })
                      ) || {};

                    if (!content) {
                      return;
                    }

                    const placeholderText = options.t?.(content) || content;
                    nodePlaceholderPositions.add(pos);
                    decorations.push(
                      Decoration.node(pos, pos + node.nodeSize, {
                        class: classNames('is-node-empty', {
                          [styles.alignCenter]: alignCenter,
                        }),
                        ...(alwaysVisible ? { 'data-placeholder-always-visible': '' } : {}),
                      })
                    );

                    if (shouldRenderWidgets) {
                      decorations.push(
                        Decoration.widget(
                          pos + 1,
                          createPlaceholderWidget(placeholderText, options.isMobile),
                          {
                            side: -1,
                            ignoreSelection: true,
                            key: `node-empty-placeholder:${placeholderText}`,
                          }
                        )
                      );
                    }

                    return true;
                  });
                }

                if (
                  editorEmptyTargetPos !== undefined &&
                  editorEmptyTargetNodeSize !== undefined &&
                  !nodePlaceholderPositions.has(editorEmptyTargetPos)
                ) {
                  decorations.push(
                    Decoration.node(
                      editorEmptyTargetPos,
                      editorEmptyTargetPos + editorEmptyTargetNodeSize,
                      {
                        class: 'is-editor-empty',
                      }
                    )
                  );

                  if (shouldRenderWidgets) {
                    decorations.push(
                      Decoration.widget(
                        editorEmptyTargetPos + 1,
                        createPlaceholderWidget(placeholderText, options.isMobile),
                        {
                          side: -1,
                          ignoreSelection: true,
                          key: `editor-empty-placeholder:${placeholderText}`,
                        }
                      )
                    );
                  }
                }

                return DecorationSet.create(doc, decorations);
              },
            },
          }),
        ];
      },
    };
  },
});

export const updatePlaceholder = (editor: Editor, placeholder: string) => {
  const tr = editor.view.state.tr.setMeta(PLACEHOLDER_UPDATE_META, placeholder);
  editor.view.dispatch(tr);
};
