import type { Node_Type, Node as RicosDocumentNode } from './../ricos-schema/next-schema/index.js';
import type { RicosExtension, RicosExtensionConfig } from './../ricos-types/index.js';
import { PmNodeType } from './../_shared/pm-node-types.js';

import { createRicosFunctionalExtension } from './create-ricos-extension/index.js';

/**
 * True when `T` is an object type declaring an `animation` property. The
 * `string extends keyof T` arm skips index-signature payloads (`ExternalNode`'s
 * `externalData: Record<string, any>` and `htmlData: any`), which structurally
 * satisfy every property name and would otherwise match.
 */
type HasAnimation<T> = T extends unknown
  ? string extends keyof T
    ? never
    : 'animation' extends keyof T
      ? true
      : never
  : never;

/** The node's own `type` if any of its properties is a payload carrying `animation`. */
type AnimatableOf<N> = N extends { type: string }
  ? true extends HasAnimation<N[keyof N]>
    ? N['type']
    : never
  : never;

/**
 * Schema node types whose data payload declares `animation`, read straight off the
 * generated document type — never hand-listed. Union-typed payloads only qualify when
 * *every* variant declares it, since `keyof` over a union is the intersection of its keys.
 */
type AnimatableSchemaType = AnimatableOf<RicosDocumentNode>;

/** BUTTON is the one schema type that maps to two PM node types. */
export type AnimatablePmType =
  | Exclude<AnimatableSchemaType, typeof Node_Type.BUTTON>
  | typeof PmNodeType.LINK_BUTTON
  | typeof PmNodeType.ACTION_BUTTON;

/**
 * The PM node types that carry `animation`. `satisfies` ties this to the schema in both
 * directions: a node type that gains `animation` in the JTD and isn't registered here
 * fails the build, and so does an entry the schema no longer declares.
 *
 * Cells (table/layout/smart-block) and structural wrappers (CAPTION, TEXT, FIGURE,
 * TABLE_ROW, COLLAPSIBLE_ITEM and its title/body children) are absent because the schema
 * itself excludes them — blocks animate as a whole, and LIST_ITEM is the only nested node
 * with an animation of its own. CARD is excluded too: it's a paging container, so its own
 * blocks animate rather than the page.
 */
const ANIMATABLE_PM_TYPE_MAP = {
  [PmNodeType.PARAGRAPH]: true,
  [PmNodeType.HEADING]: true,
  [PmNodeType.BULLETED_LIST]: true,
  [PmNodeType.ORDERED_LIST]: true,
  [PmNodeType.CHECKBOX_LIST]: true,
  [PmNodeType.LIST_ITEM]: true,
  [PmNodeType.BLOCKQUOTE]: true,
  [PmNodeType.CODE_BLOCK]: true,
  [PmNodeType.DIVIDER]: true,
  [PmNodeType.IMAGE]: true,
  [PmNodeType.VIDEO]: true,
  [PmNodeType.AUDIO]: true,
  [PmNodeType.GIF]: true,
  [PmNodeType.FILE]: true,
  [PmNodeType.GALLERY]: true,
  [PmNodeType.HTML]: true,
  [PmNodeType.EMBED]: true,
  [PmNodeType.LINK_PREVIEW]: true,
  [PmNodeType.LINK_BUTTON]: true,
  [PmNodeType.ACTION_BUTTON]: true,
  [PmNodeType.TABLE]: true,
  [PmNodeType.COLLAPSIBLE_LIST]: true,
  [PmNodeType.POLL]: true,
  [PmNodeType.APP_EMBED]: true,
  [PmNodeType.TOC]: true,
  [PmNodeType.SHAPE]: true,
  [PmNodeType.SMART_BLOCK]: true,
  [PmNodeType.LAYOUT]: true,
} satisfies Record<AnimatablePmType, true>;

export const ANIMATABLE_PM_TYPES: string[] = Object.keys(ANIMATABLE_PM_TYPE_MAP);

export const nodeAnimation = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'node-animation',
  reconfigure(config: RicosExtensionConfig, extensions: RicosExtension[]) {
    const registeredAnimatableTypes = extensions
      .filter(
        extension =>
          (extension.type === 'react-node' || extension.type === 'html-node') &&
          ANIMATABLE_PM_TYPES.includes(extension.name)
      )
      .map(({ name }) => name);
    return {
      ...config,
      addGlobalAttributes() {
        return [
          {
            types: registeredAnimatableTypes,
            attributes: {
              animation: {
                default: null,
                // Animation is an object — never serialize it into the DOM
                rendered: false,
              },
            },
          },
        ];
      },
    };
  },
  createExtensionConfig() {
    return {
      name: this.name,
    };
  },
});
