import { generateId } from './../ricos-content/index.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { RicosExtension, RicosExtensionConfig } from './../ricos-types/index.js';
import type { Node as ProseMirrorNode } from './../tiptap/pm/model.js';
import type { Transaction } from './../tiptap/pm/state.js';
import { Plugin, PluginKey, TextSelection } from './../tiptap/pm/state.js';
import { browser } from './../editor-common/index.js';

import { createRicosFunctionalExtension } from './create-ricos-extension/index.js';
import { nodeElementStyleToTiptapTextStyle } from './text-style-converters.js';

function minMax(value = 0, min = 0, max = 0): number {
  return Math.min(Math.max(value, min), max);
}

/*
  This fix a bug with Android when using setNodeType in appendTransaction.
  The bug is that the cursor is not positioned correctly after the transaction
  so we have to manually set the cursor position.
*/
const handleAndroidEnterBug = (tr: Transaction, pos: number) => {
  const { doc } = tr;
  const { from, to } = { from: pos + 1, to: pos + 1 };

  const minPos = TextSelection.atStart(doc).from;
  const maxPos = TextSelection.atEnd(doc).to;
  const resolvedFrom = minMax(from, minPos, maxPos);
  const resolvedEnd = minMax(to, minPos, maxPos);
  const selection = TextSelection.create(doc, resolvedFrom, resolvedEnd);
  tr.setSelection(selection);
};

const handleBlockquoteParagraphId = (node: ProseMirrorNode, usedIds: Record<string, boolean>) => {
  let paragraphId: string | undefined;
  let nodeParagraphId: string | undefined;
  let shouldUpdateBlockquoteParagraphId = false;
  if (node.type.name === Node_Type.BLOCKQUOTE) {
    nodeParagraphId = node.attrs.paragraphId;
    paragraphId = nodeParagraphId && !usedIds[nodeParagraphId] ? nodeParagraphId : generateId();

    shouldUpdateBlockquoteParagraphId = nodeParagraphId !== paragraphId;
  }
  return { paragraphId, shouldUpdateBlockquoteParagraphId };
};

export const uniqueId = createRicosFunctionalExtension({
  type: 'extension',
  groups: [],
  name: 'unique-id',
  reconfigure(config: RicosExtensionConfig, extensions: RicosExtension[]) {
    return {
      ...config,
      addGlobalAttributes() {
        return [
          {
            types: extensions
              .filter(
                extension =>
                  (extension.type === 'react-node' || extension.type === 'html-node') &&
                  !extension.groups.includes('text')
              )
              .map(({ name }) => name),
            attributes: {
              id: {
                default: null,
              },
            },
          },
        ];
      },
    };
  },
  createExtensionConfig() {
    return {
      name: this.name,
      priority: 2, // should be before contentDiff
      addProseMirrorPlugins() {
        return [
          new Plugin({
            key: new PluginKey('unique-id'),
            appendTransaction: (_transactions, oldState, newState) => {
              if (newState.doc === oldState.doc) {
                return;
              }
              const tr = newState.tr;
              const usedIds: Record<string, boolean> = {};

              const { selection } = oldState;
              const marks = selection.$to.parentOffset && selection.$from.marks();

              newState.doc.descendants((node, pos) => {
                const nodeId: string = node.attrs.id;
                const id = nodeId && !usedIds[nodeId] ? nodeId : generateId();
                usedIds[id] = true;
                const shouldUpdate = nodeId !== id;

                const { paragraphId, shouldUpdateBlockquoteParagraphId } =
                  handleBlockquoteParagraphId(node, usedIds);
                if (paragraphId) {
                  usedIds[paragraphId] = true;
                }

                if (node.isBlock && (shouldUpdate || shouldUpdateBlockquoteParagraphId)) {
                  /*
                    Fix bug in Android when textStyle is not preserved in new lines.
                    The styles arrived in node.attrs.style as string so we need to manually
                    create the textStyle object.
                  */
                  if (browser.android && node.attrs.style) {
                    const { style, textStyle } = nodeElementStyleToTiptapTextStyle(
                      node.attrs.style
                    );
                    tr.setNodeMarkup(pos, undefined, {
                      ...node.attrs,
                      id,
                      marks,
                      style,
                      textStyle,
                      ...(paragraphId ? { paragraphId } : {}),
                    });
                  } else {
                    tr.setNodeMarkup(pos, undefined, {
                      ...node.attrs,
                      id,
                      marks,
                      ...(paragraphId ? { paragraphId } : {}),
                    });
                  }
                  tr.setMeta('unique-id', true); // do not remove this meta, it's used in content-diff

                  // this should run before ensureMarks becasuse it resets the marks
                  // also ignore tralingNode insertion
                  if (browser.android && !tr.getMeta('trailingNodeInsertion')) {
                    handleAndroidEnterBug(tr, pos);
                  }

                  marks && tr.ensureMarks(marks);
                }
              });

              return tr;
            },
          }),
        ];
      },
    };
  },
});
