import classNames from 'classnames';
import { find } from 'linkifyjs';

import type { LinkData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Link_Target } from './../../ricos-schema/next-schema/index.js';
import type {
  DOMOutputSpec,
  ExtensionProps,
  MarkConfig,
  RicosExtension,
} from './../../ricos-types/index.js';
import type { NamedLinkData } from './../../_shared/link/types.js';
import type { DeepPartial } from './../../_shared/ts-utils/deep-partial.js';
import type { ExtendedRegExpMatchArray } from './../../tiptap/core/index.js';
import type { Plugin } from './../../tiptap/pm/state.js';
import type { TiptapAdapterServices } from './../../tiptap-editor/initialize-tiptap-adapter.js';

import { createRicosMarkExtension } from '../create-ricos-extension/index.js';
import { clickHandler } from '../link/helpers/click-handler.js';
import styles from '../statics/styles-scss.js';
import { WEB_LINK } from './data-hooks.js';
import { pasteHandler } from './helpers/paste-handler.js';
import { LINK_PARSE_HTML_TAG } from './link-parse-html-tag.js';
import { RicosLink } from './models.js';
import { cleanAndSetSelection, getSelectedMarkRangeByTypeNames } from './utils.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    link: {
      /**
       * Set a link mark
       */
      setLink: (attributes: DeepPartial<LinkData>) => ReturnType;
      /**
       * Toggle a link mark
       */
      toggleLink: (attributes: DeepPartial<LinkData>) => ReturnType;
      /**
       * Unset a link mark
       */
      unsetLink: () => ReturnType;
    };
  }
}

export const link = createRicosMarkExtension({
  type: 'mark',
  groups: [],
  name: Decoration_Type.LINK,
  reconfigure: (
    config: MarkConfig,
    _extensions: RicosExtension[],
    props: ExtensionProps,
    _settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) => {
    const { rel, relValue, anchorTarget = Link_Target.BLANK } = props;
    const actualRel = {
      noreferrer: rel?.noreferrer ?? true,
      ...[rel?.nofollow ? { nofollow: true } : {}],
      ...[rel?.sponsored ? { sponsored: true } : {}],
    };

    const autoUnderline = services.editorProps.generalLinkSettings?.autoUnderline ?? true;

    return {
      ...config,
      addOptions: () => ({
        inclusive: false,
        openOnClick: false,
        linkOnPaste: true,
        HTMLAttributes: { link: {} },
        defaultLink: RicosLink.of('', anchorTarget, relValue, actualRel),
        autoUnderline,
      }),
    };
  },
  createExtensionConfig({ markPasteRule }) {
    return {
      name: this.name,
      keepOnSplit: false,

      priority: 1000,

      inclusive() {
        return this.options.inclusive;
      },

      addAttributes() {
        return RicosLink.getLinkDefaults();
      },

      parseHTML() {
        return [
          {
            tag: LINK_PARSE_HTML_TAG,
            consuming: false,
            getAttrs: (node: $TSFixMe) => {
              const url = node.getAttribute('href') || '';
              const target = node.getAttribute('target') || '';
              const rel = node.getAttribute('rel') || '';
              return { link: RicosLink.of(url, target, rel).toLink() };
            },
            priority: 51,
          },
        ];
      },

      renderHTML({ HTMLAttributes }) {
        const { link, linkInViewer } = styles;
        const classes = classNames(link, linkInViewer);
        let {
          url: href,
          rel,
          target,
        } = HTMLAttributes.link
          ? RicosLink.fromLink(HTMLAttributes.link).toHtmlAttributes()
          : this.options.defaultLink.toHtmlAttributes();

        return [
          'a',
          { href, rel: (rel += ' noopener'), target, class: classes, 'data-hook': WEB_LINK },
          0,
        ] as DOMOutputSpec;
      },

      addCommands() {
        return {
          setLink:
            (link: DeepPartial<NamedLinkData>) =>
            ({ commands, tr, state, chain }) => {
              cleanAndSetSelection(
                this.name,
                Decoration_Type.ANCHOR,
                commands.unsetAnchor,
                state.schema,
                tr.selection,
                state.doc,
                commands,
                link.link?.defaultName || link.link?.url || ''
              );

              let setLinkChain = chain().setMark(this.name, link);

              if (this.options.autoUnderline) {
                setLinkChain = setLinkChain.setUnderline();
              }

              return setLinkChain.setMeta('preventAutolink', true).run();
            },
          toggleLink:
            (link: DeepPartial<LinkData>) =>
            ({ chain }) => {
              return chain()
                .toggleMark(this.name, link, { extendEmptyMarkRange: true })
                .setMeta('preventAutolink', true)
                .run();
            },
          unsetLink:
            () =>
            ({ tr, chain, state }) => {
              const { from, to } = getSelectedMarkRangeByTypeNames(
                [this.name],
                state.schema,
                tr.selection
              );

              let unsetLinkChain = chain().setTextSelection({ from, to }).unsetMark(this.name);

              if (this.options.autoUnderline) {
                unsetLinkChain = unsetLinkChain.unsetUnderline();
              }

              return unsetLinkChain.setMeta('preventAutolink', true).run();
            },
        };
      },

      addPasteRules() {
        return [
          markPasteRule({
            find: (text: string) => {
              return find(text)
                .filter(link => {
                  if (this.options.validate) {
                    return this.options.validate(link.value);
                  }

                  return true;
                })
                .filter(link => link.isLink)
                .map(link => ({
                  text: link.value,
                  index: link.start,
                  data: link,
                }));
            },
            type: this.type,
            getAttributes: (match: ExtendedRegExpMatchArray) => {
              return this.options.defaultLink.setUrl(match.data?.href || '');
            },
          }),
        ];
      },

      addProseMirrorPlugins() {
        const plugins: Plugin[] = [];

        if (this.options.openOnClick) {
          plugins.push(
            clickHandler({
              type: this.type,
            })
          );
        }

        if (this.options.linkOnPaste) {
          plugins.push(
            pasteHandler({
              editor: this.editor,
              type: this.type,
              defaultLink: this.options.defaultLink,
            })
          );
        }

        return plugins;
      },
    };
  },
});
